messages.content:
Write a single self-contained HTML file with a 3D animation using three.js. three.js r160 is available as an ES module at './three.module.js' -- import it with:
  import * as THREE from './three.module.js';
Scene: two cars race on a straight track toward a visible finish line. One car is bright RED, the other bright BLUE. The blue car leads early, then the red car accelerates, overtakes mid-race, and wins. After the red car crosses the finish line the race resets and loops forever. Both cars must be clearly visible and large enough to follow throughout (fill a meaningful part of the frame). Simple ground and sky, camera keeps both cars in view. No external assets besides the three.js import. Output ONLY the HTML in one code block.

response.text:
```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Three.js Car Race</title>
    <style>
        body {
            margin: 0;
            overflow: hidden;
            background-color: #87CEEB; /* Sky color */
            font-family: Arial, sans-serif;
        }
        #info {
            position: absolute;
            top: 20px;
            width: 100%;
            text-align: center;
            color: white;
            font-size: 24px;
            font-weight: bold;
            text-shadow: 2px 2px 4px #000000;
            pointer-events: none;
            z-index: 10;
        }
    </style>
</head>
<body>
    <div id="info">Red Wins!</div>

    <script type="module">
        import * as THREE from './three.module.js';

        // --- Configuration ---
        const TRACK_LENGTH = 200;
        const FINISH_LINE_Z = 50;
        const START_Z = 0;
        const LANE_WIDTH = 14;
        const CAR_WIDTH = 4;
        const CAR_HEIGHT = 2;
        const CAR_LENGTH = 8;

        // --- Scene Setup ---
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x87CEEB); // Sky blue
        scene.fog = new THREE.Fog(0x87CEEB, 20, 100);

        const camera = new THREE.PerspectiveCamera(60, window.innerWidth / window.innerHeight, 0.1, 1000);
        camera.position.set(0, 15, 15);
        camera.lookAt(0, 0, -20);

        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.shadowMap.enabled = true;
        document.body.appendChild(renderer.domElement);

        // --- Lights ---
        const ambientLight = new THREE.AmbientLight(0xffffff, 0.6);
        scene.add(ambientLight);

        const dirLight = new THREE.DirectionalLight(0xffffff, 0.8);
        dirLight.position.set(20, 50, 20);
        dirLight.castShadow = true;
        dirLight.shadow.camera.top = 50;
        dirLight.shadow.camera.bottom = -50;
        dirLight.shadow.camera.left = -50;
        dirLight.shadow.camera.right = 50;
        dirLight.shadow.mapSize.width = 2048;
        dirLight.shadow.mapSize.height = 2048;
        scene.add(dirLight);

        // --- Environment ---
        // Ground
        const groundGeometry = new THREE.PlaneGeometry(200, 500);
        const groundMaterial = new THREE.MeshStandardMaterial({ color: 0x333333 });
        const ground = new THREE.Mesh(groundGeometry, groundMaterial);
        ground.rotation.x = -Math.PI / 2;
        ground.receiveShadow = true;
        scene.add(ground);

        // Finish Line (Checkered)
        const finishGroup = new THREE.Group();
        const finishGeo = new THREE.PlaneGeometry(CAR_LENGTH, 2);
        const finishMat = new THREE.MeshBasicMaterial({ color: 0xffffff });
        const whiteLine = new THREE.Mesh(finishGeo, finishMat);
        whiteLine.position.set(0, 0.1, -FINISH_LINE_Z);
        whiteLine.receiveShadow = true;

        const blackLine = new THREE.Mesh(finishGeo, new THREE.MeshBasicMaterial({ color: 0x000000 }));
        blackLine.position.set(0, 0.1, -FINISH_LINE_Z + 1);
        blackLine.receiveShadow = true;

        // Add repeating checkered pattern logic
        for(let i = -1; i < 10; i++) {
            const z = -FINISH_LINE_Z + (i * 0.5);
            const mesh = i % 2 === 0 ? whiteLine : blackLine;
            mesh.position.z = z;
            finishGroup.add(mesh);
        }
        scene.add(finishGroup);

        // --- Car Factory ---
        function createCar(color, isRed) {
            const carGroup = new THREE.Group();

            // Chassis
            const chassisGeo = new THREE.BoxGeometry(CAR_WIDTH, CAR_HEIGHT, CAR_LENGTH);
            const chassisMat = new THREE.MeshStandardMaterial({ color: color });
            const chassis = new THREE.Mesh(chassisGeo, chassisMat);
            chassis.position.y = CAR_HEIGHT / 2;
            chassis.castShadow = true;
            chassis.receiveShadow = true;
            carGroup.add(chassis);

            // Cabin
            const cabinGeo = new THREE.BoxGeometry(CAR_WIDTH * 0.6, CAR_HEIGHT * 0.6, CAR_LENGTH * 0.5);
            const cabinMat = new THREE.MeshStandardMaterial({ color: 0x333333 });
            const cabin = new THREE.Mesh(cabinGeo, cabinMat);
            cabin.position.y = CAR_HEIGHT * 1.4;
            cabin.position.z = -CAR_LENGTH * 0.1;
            cabin.castShadow = true;
            carGroup.add(cabin);

            // Wheels
            const wheelGeo = new THREE.CylinderGeometry(1, 1, 1, 16);
            const wheelMat = new THREE.MeshStandardMaterial({ color: 0x111111 });

            const positions = [
                { x: -CAR_WIDTH/2 - 0.5, z: -CAR_LENGTH/2 + 1 },
                { x: CAR_WIDTH/2 + 0.5, z: -CAR_LENGTH/2 + 1 },
                { x: -CAR_WIDTH/2 - 0.5, z: CAR_LENGTH/2 - 1 },
                { x: CAR_WIDTH/2 + 0.5, z: CAR_LENGTH/2 - 1 }
            ];

            positions.forEach(pos => {
                const wheel = new THREE.Mesh(wheelGeo, wheelMat);
                wheel.rotation.z = Math.PI / 2;
                wheel.position.set(pos.x, 0.5, pos.z);
                wheel.castShadow = true;
                carGroup.add(wheel);
            });

            // Headlights
            const lightGeo = new THREE.BoxGeometry(0.5, 0.2, 0.1);
            const lightMat = new THREE.MeshBasicMaterial({ color: 0xffffaa });

            const hl1 = new THREE.Mesh(lightGeo, lightMat);
            hl1.position.set(-0.8, CAR_HEIGHT, CAR_LENGTH/2 + 0.5);
            carGroup.add(hl1);

            const hl2 = new THREE.Mesh(lightGeo, lightMat);
            hl2.position.set(0.8, CAR_HEIGHT, CAR_LENGTH/2 + 0.5);
            carGroup.add(hl2);

            return carGroup;
        }

        // --- The Racers ---
        const redCar = createCar(0xff0000, true);
        const blueCar = createCar(0x0000ff, false);

        scene.add(redCar);
        scene.add(blueCar);

        // --- State Variables ---
        let racePhase = 'start'; // start, racing, finished, reset
        let blueSpeed = 0;
        let redSpeed = 0;
        let bluePos = START_Z;
        let redPos = START_Z;
        let finishCrossed = false;

        // --- Logic ---
        function updatePhysics(dt) {
            if (racePhase === 'start') {
                // Phase 1: Blue accelerates fast, Red stays slow
                blueSpeed = Math.min(blueSpeed + 200 * dt, 400);
                redSpeed = 50; // Slow start

                bluePos += blueSpeed * dt;
                redPos += redSpeed * dt;

                if (bluePos > FINISH_LINE_Z - 10) {
                    racePhase = 'racing';
                }
            } 
            else if (racePhase === 'racing') {
                // Phase 2: Blue maintains speed, Red accelerates aggressively
                blueSpeed = 380; // Slightly slower than max
                redSpeed = Math.min(redSpeed + 300 * dt, 800); // Red overtakes

                bluePos += blueSpeed * dt;
                redPos += redSpeed * dt;

                // Check for finish
                if (!finishCrossed && redPos >= FINISH_LINE_Z) {
                    finishCrossed = true;
                    racePhase = 'finished';
                }
            } 
            else if (racePhase === 'finished') {
                // Phase 3: Show victory, then reset
                bluePos = START_Z;
                redPos = START_Z;
                blueSpeed = 0;
                redSpeed = 0;

                // Simple lerp reset
                bluePos += (START_Z - bluePos) * 5 * dt;
                redPos += (START_Z - redPos) * 5 * dt;

                if (bluePos < 2) {
                    racePhase = 'start';
                    finishCrossed = false;
                }
            }
        }

        function updateCamera() {
            // Smooth camera follow
            const targetZ = (bluePos + redPos) / 2;
            // Keep camera slightly ahead of the leader
            const cameraTargetZ = targetZ - 20;

            // Lerp camera position
            camera.position.z += (cameraTargetZ - camera.position.z) * 0.1;
            camera.lookAt(0, 0, cameraTargetZ - 5);
        }

        function renderLoop(time) {
            const dt = 0.016; // Approximate delta time

            updatePhysics(dt);
            updateCamera();

            // Update Car Positions
            redCar.position.z = redPos;
            blueCar.position.z = bluePos;

            // Add some steering wobble to make it look alive
            redCar.position.x = Math.sin(time * 0.002) * 1;
            blueCar.position.x = Math.sin(time * 0.003 + 1) * 1;

            // Tilt cars slightly based on speed
            redCar.rotation.z = -redSpeed * 0.0001;
            blueCar.rotation.z = -blueSpeed * 0.0001;

            // Update UI
            const info = document.getElementById('info');
            if (racePhase === 'start') {
                info.innerText = "Blue is winning...";
                info.style.color = '#0000ff';
            } else if (racePhase === 'racing') {
                if (redPos > bluePos) {
                    info.innerText = "Red is overtaking!";
                    info.style.color = '#ff0000';
                } else {
                    info.innerText = "Blue leads!";
                    info.style.color = '#0000ff';
                }
            } else if (racePhase === 'finished') {
                info.innerText = "RED WINS!";
                info.style.color = '#ff0000';
                info.style.fontSize = "40px";
            }

            renderer.render(scene, camera);
            requestAnimationFrame(renderLoop);
        }

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        // Start
        requestAnimationFrame(renderLoop);

    </script>
</body>
</html>
```
